  ?z ref:hasExternalReference ?ext .
  ?ext ref:timeseriesId ?tsid .
  ?ext a ?pclass .
} LIMIT 200

SELECT ?zone ?lbl WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?lbl }
}

